  if ('fills' in n && Array.isArray(n.fills)) o.fills = n.fills.map(f=>f.type==='SOLID'?`SOLID ${f.color?('#'+[f.color.r,f.color.g,f.color.b].map(v=>Math.round(v*255).toString(16).padStart(2,'0')).join('')):''} op=${f.opacity} vis=${f.visible}`:f.type);
  if ('strokes' in n && n.strokes && n.strokes.length) { o.strokes = n.strokes.map(f=>f.type); o.strokeWeight = n.strokeWeight; }
  if ('cornerRadius' in n && n.cornerRadius !== figma.mixed) o.cornerRadius = n.cornerRadius;
  if (n.type === 'TEXT') {
    o.chars = n.characters;
    const f = n.fontName; o.font = f===figma.mixed?'MIXED':`${f.family} ${f.style}`;
    o.fontSize = n.fontSize;
    o.textAlign = n.textAlignHorizontal;
    o.lineHeight = JSON.stringify(n.lineHeight);
  }
  if ('effects' in n && n.effects && n.effects.length) o.effects = n.effects.map(e=>`${e.type} r=${e.radius} op=${e.opacity}`);
  if (n.type === 'INSTANCE' || n.type === 'COMPONENT') { o.componentId = n.type==='INSTANCE'?n.mainComponent.id:undefined; o.desc = n.description; }
  if ('layoutMode' in n && n.layoutMode !== 'NONE') o.layout = `${n.layoutMode} gap=${n.itemSpacing} pad=${n.paddingTop},${n.paddingRight},${n.paddingBottom},${n.paddingLeft}`;
  out.push(pad + JSON.stringify(o));
  if ('children' in n) for (const c of n.children) dump(c, depth+1, out);
  return out;
}
