media.clipsContent = false;

const coinIds = {};
let i = 0;
for (const c of coins) {
  const src = await figma.getNodeByIdAsync(coinSrc[c]);
  const copy = src.clone();
  media.appendChild(copy);
  copy.x = 16 + (i % 6) * 66;
  copy.y = 16 + Math.floor(i / 6) * 66;
  copy.name = 'C_' + c;
  const inst = copy.createInstance();
  inst.name = 'C_' + c;
  media.appendChild(inst);
  inst.x = copy.x; inst.y = copy.y;
  copy.visible = false;
  coinIds[c] = inst.id;
  i++;
}

const iconIds = {};
let j = 0;
for (const [n, id] of Object.entries(icons)) {
  const src = await figma.getNodeByIdAsync(id);
  const cp = src.clone();
  media.appendChild(cp);
  cp.x = 16 + (j % 8) * 50;
  cp.y = 380;
  cp.name = 'I_' + n;
  const inst = cp.createInstance();
  inst.name = 'I_' + n;
  media.appendChild(inst);
  inst.x = cp.x; inst.y = cp.y;
  cp.visible = false;
  iconIds[n] = inst.id;
  j++;
}

