  const items = { screen: screenName, id: root.id, w: root.width, h: root.height, overflow: [], textOut: [] };
  const walk = n => {
    if ('children' in n) for (const c of n.children) {
      if (c.x + c.width > n.width + 0.5 && n.clipsContent) items.overflow.push({ parent: n.name, child: c.name, right: Math.round(c.x + c.width), parentW: Math.round(n.width) });
      walk(c);
    }
    if (n.type === 'TEXT') {
      // detect clipped text: rendered height vs set height
      if (n.textAutoResize === 'HEIGHT' && n.height > 400) items.textOut.push({ name: n.name, chars: n.characters.slice(0,30), h: Math.round(n.height) });
    }
  };
  walk(root);
  items.children = root.children.map(c => c.name);
  report.push(items);
}
return JSON.stringify(report, null, 1);

