const page = figma.root.children.find(p => p.id === '4:2');
await figma.setCurrentPageAsync(page);
const g = n => page.findOne(x => x.name === n);
const S = { wallet:g('01_Wallet'), discovery:g('02_Discovery'), strategy:g('03_Strategy'), amount:g('04_Invest_Amount'), success:g('05_Invest_Success') };
const dest = { wallet:S.wallet.id, discovery:S.discovery.id, strategy:S.strategy.id, amount:S.amount.id, success:S.success.id };

const ps = {}; for (const s of await figma.getLocalPaintStylesAsync()) ps[s.name]=s.paints;
const white = ps['Surface/White'].map(p=>({...p}));
const sh4 = S.amount.findOne(n=>n.name==='Sheet');
const footer4 = sh4.findOne(n=>n.name==='Sheet Footer');
const fid = footer4.findOne(n=>n.type==='INSTANCE' && n.name==='Face ID');
if (fid) {
  for (const v of fid.findAll(c => c.type === 'VECTOR')) {
    if (v.fills.length) v.fills = white;
    if (v.strokes.length) v.strokes = white;
  }
  fid.x = 98; fid.y = 34;
}

const R = to => [{ trigger:{ type:'ON_CLICK' }, actions:[{ type:'NODE', destinationId: dest[to], navigation:'NAVIGATE', transition:{ type:'DISSOLVE', duration:0.2, easing:{ type:'EASE_OUT' } } }] }];
let ok = 0; const errors = [];
const L = (node, to, tag) => {
  if (!node) { errors.push(tag+':missing'); return; }
  try { node.reactions = R(to); ok++; } catch (e) { errors.push(tag+':'+e.message.slice(0,50)); }
};
const wNav = S.wallet.findOne(n=>n.name==='Bottom Nav');
L(wNav.findOne(n=>n.name==='Nav Pill'), 'discovery', 'walletNav');
wNav.children.filter(n=>n.name.startsWith('Page Dot')).forEach(d=>L(d,'discovery','walletDot'));
const dNav = S.discovery.findOne(n=>n.name==='Bottom Nav');
dNav.children.filter(n=>n.name.startsWith('Page Dot')).forEach(d=>L(d,'wallet','discDot'));
L(S.discovery.findOne(n=>n.name==='Strategy Aggressive Growth'), 'strategy', 'aggressive');
const sh3 = S.strategy.findOne(n=>n.name==='Sheet');
L(sh3.findOne(n=>n.name==='Sheet Footer').findOne(n=>n.name==='Invest Button'), 'amount', 'invest');
L(sh3.findOne(n=>n.name==='Close'), 'discovery', 'stratClose');
L(sh4.findOne(n=>n.name==='Back'), 'strategy', 'amountBack');
L(footer4.findOne(n=>n.name==='Hold to Invest'), 'success', 'hold');
const sh5 = S.success.findOne(n=>n.name==='Sheet');
L(sh5.findOne(n=>n.name==='Close'), 'discovery', 'succClose');
L(sh5.findOne(n=>n.name==='Sheet Footer').findOne(n=>n.name==='View Pocket'), 'wallet', 'viewPocket');
return 'linked=' + ok + ' faceid=' + (fid ? 'ok' : 'none') + ' errors=' + (errors.join(',') || 'none');

const page = figma.root.children.find(p => p.id === '4:2');
await figma.setCurrentPageAsync(page);
const names = ['01_Wallet','02_Discovery','03_Strategy','04_Invest_Amount','05_Invest_Success'];
let total = 0; const lines = [];
for (const nm of names) {
  const root = page.findOne(n => n.name === nm);
  if (!root) { lines.push(nm + ': MISSING'); continue; }
  let count = 0; const targets = [];
  const walk = n => {
    if (n.reactions && n.reactions.length) {
      for (const r of n.reactions) for (const a of r.actions) {
        count++;
        if (a.destinationId) targets.push(a.destinationId);
      }
    }
    if ('children' in n) for (const c of n.children) walk(c);
  };
  walk(root);
  total += count;
  lines.push(nm + ': ' + count + ' link(s) -> ' + [...new Set(targets)].join(','));
}
return lines.join('\n') + '\nTOTAL=' + total;

