const page = figma.root.children.find(p => p.id === '4:2');
await figma.setCurrentPageAsync(page);
const removed = [];
for (const nm of ['__review_body','__review_coins']) {
  const n = page.findOne(x => x.name === nm);
  if (n) { n.remove(); removed.push(nm); }
}
const order = ['01_Wallet','02_Discovery','03_Strategy','04_Invest_Amount','05_Invest_Success'];
const rows = order.map(nm => {
  const f = page.findOne(n => n.name === nm && n.type === 'FRAME');
  if (!f) return nm + ' MISSING';
  let links = 0;
  const walk = n => { if (n.reactions && n.reactions.length) links += n.reactions.length; if ('children' in n) n.children.forEach(walk); };
  walk(f);
  return nm + ' | ' + f.id + ' | ' + Math.round(f.width) + 'x' + Math.round(f.height) + ' | links=' + links;
});
const comps = page.findAll(n => n.type === 'COMPONENT' || n.type === 'COMPONENT_SET').length;
return 'removed=' + removed.join(',') + '\n' + rows.join('\n') + '\ncomponent nodes=' + comps;

