const page = figma.root.children.find(p => p.id === '4:2');
await figma.setCurrentPageAsync(page);
const g = n => page.findOne(x => x.name === n);
const w = g('01_Wallet'), d = g('02_Discovery');
const res = [];
const tryDrag = (node, destId, tag) => {
  const base = [{ trigger:{ type:'ON_CLICK' }, actions:[{ type:'NODE', destinationId: destId, navigation:'NAVIGATE', transition:{ type:'DISSOLVE', duration:0.2, easing:{ type:'EASE_OUT' } } }] }];
  const withDrag = [{ trigger:{ type:'ON_DRAG' }, actions:[{ type:'NODE', destinationId: destId, navigation:'NAVIGATE', transition:{ type:'DISSOLVE', duration:0.2, easing:{ type:'EASE_OUT' } } }] }, ...base];
  try { node.reactions = withDrag; res.push(tag + ': drag ok'); }
  catch (e) { res.push(tag + ': drag rejected'); }
};
tryDrag(w.findOne(n=>n.name==='Scroll'), d.id, 'wallet scroll');
tryDrag(d.findOne(n=>n.name==='Scroll'), w.id, 'discovery scroll');
return res.join(' | ');

const page = figma.root.children.find(p => p.id === '4:2');
await figma.setCurrentPageAsync(page);
const w = page.findOne(n => n.name === '01_Wallet');
const d = page.findOne(n => n.name === '02_Discovery');
const node = w.findOne(n => n.name === 'Scroll');
const out = [];
const act = [{ type:'NODE', destinationId: d.id, navigation:'NAVIGATE', transition:{ type:'DISSOLVE', duration:0.2, easing:{ type:'EASE_OUT' } } }];
for (const trig of ['ON_DRAG','ON_SWIPE','ON_PRESS','MOUSE_ENTER','ON_CLICK']) {
  try { node.reactions = [{ trigger:{ type: trig }, actions: act }]; out.push(trig + '=ok'); node.reactions = []; }
  catch (e) { out.push(trig + '=' + e.message.replace(/\n/g,' ').slice(0,90)); }
}
// restore the click link that is required by the brief
node.reactions = [{ trigger:{ type:'ON_CLICK' }, actions: act }];
return out.join(' || ');
